        return if (ext.isNullOrBlank()) name else "$name.$ext"
    }

    /** Возвращает человекочитаемое место сохранения. */
    @Throws(IOException::class)
    fun saveBytes(context: Context, fileName: String, mime: String?, bytes: ByteArray): String {
