                     if (view != null && request.isForMainFrame) {
                         val wantDesktop = uaFor(nextUrl) != null
                         val isDesktop = view.settings.userAgentString == ExtensionStore.DESKTOP_UA
                         if (wantDesktop != isDesktop) {
