    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) {
        throw UnsupportedOperationException("Picture-in-picture requires Android 8.0+")
    }
    val b = PictureInPictureParams.Builder().setAspectRatio(Rational(16, 9))
